 const pages=[];let p=new Page(1);pages.push(p);p.heading(sample?'MUESTRA FICTICIA · NO ES TU RESULTADO':'TU CUADERNO PERSONAL','Nueve formas de mirarte');const aliasEnd=p.para(alias.slice(0,40),44,158,507,17);p.text(`${date}  /  ${age} años  /  ${result.answered} de 54 respuestas`,44,Math.max(192,aliasEnd+8),10,muted);
 const pts=TYPES.map(t=>{const a=(t.id*40-90)*Math.PI/180;return {x:297+140*Math.cos(a),y:392+140*Math.sin(a),a}}),point=n=>pts[n-1];for(const [a,b] of [[1,4],[4,2],[2,8],[8,5],[5,7],[7,1],[3,6],[6,9],[9,3]])p.line(point(a).x,point(a).y,point(b).x,point(b).y,'#d5dbd7');
