 p.rect(44,641,507,119,'#eaf0ec');p.para(headline,62,658,471,14);p.para('Una invitación a observarte. No mide inteligencia, no es diagnóstico y no certifica un tipo de personalidad.',62,708,471,10);
 p=new Page(2);pages.push(p);p.heading('01 / TU MAPA','Las nueve tendencias');p.para('Cada fila resume hasta seis respuestas. No hay tipos mejores. La puntuación describe lo que has declarado hoy.',44,153,507,11,muted);
 result.rows.forEach((r,i)=>{const y=221+i*47;p.text(`${r.id}  ${r.name}`,44,y,12,ink,true);p.rect(213,y+4,216,9,'#e5e9e2');if(r.score!==null)p.rect(213,y+4,216*(r.score-1)/4,9,r.color);p.text(r.score===null?'Sin dato':r.score.toFixed(2)+' / 5',449,y,10);p.text(r.answered+'/6',512,y+19,8,muted)});
 p.para('Cómo se calcula: media de las respuestas (1-5), invirtiendo dos frases por tendencia. Se requieren al menos 4 de 6 para mostrar una media, y las nueve medias para comparar. Es una regla editorial, no un baremo validado.',44,665,507,10,muted);p.para('Diferencias de hasta 0,25 puntos se muestran como próximas. No equivalen a un intervalo de confianza. Con muchas puntuaciones iguales, revisa ejemplos reales antes de sacar conclusiones.',44,733,507,10,muted);
