 y+=22;p.text('EXPLORA UNA SITUACIÓN REAL',44,y,10,gold,true);y+=22;for(let i=0;i<coach.questions.length;i++)y=p.para(`${i+1}. ${coach.questions[i]}`,44,y+7,507,11);
