 yy+=20;p.text('REFERENCIAS Y ALCANCE',44,yy,10,gold,true);yy=p.para('Riso y Hudson: The Wisdom of the Enneagram. Helen Palmer: The Enneagram. Daniels y Price: The Essential Enneagram. Bibliografía y materiales públicos consultados; no reproducción de sus tests. Las propuestas de coaching son ejercicios originales de Coco, sin acreditación de esas escuelas.',44,yy+23,507,9.5);
 yy=p.para('La revisión de Hook y colaboradores (2021, DOI 10.1002/jclp.23097) encontró evidencia mixta. Este cuestionario no tiene validación psicométrica; no asigna alas, subtipos ni niveles de salud. Para menores se usa como conversación acompañada, sin un eneatipo dominante.',44,yy+9,507,9.5);p.text('Método y enlaces: cocoenforma.com/explora/metodo.html',44,yy+14,10,muted);
 if(yy+30>786||pages.length!==REPORT_PAGES)throw Error('Invalid coaching report layout');
 const objects=['<< /Type /Catalog /Pages 2 0 R >>','','','',''];
